7587	            .find(|s| s.name == stage)
7588	            .and_then(|s| s.subject.as_ref())
7589	            .and_then(|name| review.artifacts.get(name))
7590	            .cloned();
7591	        let (Some(run), Some(subject)) = (review.run.clone(), subject) else {
7592	            log::warn!(
7593	                "ticket {} {stage}/{number}: revise has no review run or reviewed copy",
7594	                t.id
7595	            );
7596	            return Ok(());
7597	        };
7598	        let view = match self.ask(Body::Workflow { run: run.clone() })? {
7599	            Reply::Workflow { run } => run,
7600	            other => {
7601	                log::warn!(
7602	                    "ticket {} {stage}/{number}: revise: the run could not be read ({other:?})",
7603	                    t.id
7604	                );
7605	                return Ok(());
7606	            }
7607	        };
