/// A `revise` answer to `finalize`: the owner's note becomes the
/// next round's feedback file beside the reviewed copy, and
/// `workflow.object` opens that round, for the planner to answer and
/// the reviewer to re-read. A run no longer finished is left alone;
/// the next poll asks `finalize` again if it finishes. A refusal
/// pops the revision (in `apply_reply`) and the file goes with it,
/// so the next poll asks afresh. A lost reply keeps both: the round
/// may have started, and recovery asks about the send. The port's
/// `NO_ANSWER` is a lost reply too, since the app still has the
/// request. A revision of a round whose earlier send never opened it
/// is replaced, so each round has one, naming who answered last.
fn revise(
    &mut self,
    t: &mut Ticket,
    ps: &mut ProjectState,
    p: &Pipeline,
    decision: usize,
    attempt: Option<&(String, u32)>,
    now_ms: u64,
) -> Result<()> {
    let DecisionState::Answered { note, by, .. } = &t.decisions[decision].state else {
        return Ok(());
    };
    let (text, by) = (note.clone().unwrap_or_default(), by.clone());
    let Some((stage, number)) = attempt.cloned() else {
        return Ok(());
    };
    let Some(review) = find_attempt(t, &stage, number) else {
        return Ok(());
    };
    let subject = p
        .stages
        .iter()
        .find(|s| s.name == stage)
        .and_then(|s| s.subject.as_ref())
        .and_then(|name| review.artifacts.get(name))
        .cloned();
    let (Some(run), Some(subject)) = (review.run.clone(), subject) else {
        log::warn!(
            "ticket {} {stage}/{number}: revise has no review run or reviewed copy",
            t.id
        );
        return Ok(());
    };
    let view = match self.ask(Body::Workflow { run: run.clone() })? {
        Reply::Workflow { run } => run,
        other => {
            log::warn!(
                "ticket {} {stage}/{number}: revise: the run could not be read ({other:?})",
                t.id
            );
            return Ok(());
        }
    };
    if !matches!(view.state, RunState::Converged | RunState::AtCap) {
        log::warn!(
            "ticket {} {stage}/{number}: revise: the review is no longer finished",
            t.id
        );
        return Ok(());
    }
    let round = view.round + 1;
    let file = crate::report::round_file(&subject, round);
    let body = format!("{}\n\n{}\n", crate::OWNER_ROUND_HEADING, text.trim_end());
    crate::store::atomic_write(&file, body.as_bytes())?;
    if let Some(review) = find_attempt_mut(t, &stage, number) {
        review.revisions.retain(|r| r.round != round);
        review.revisions.push(crate::ticket::Revision {
            round,
            by,
            at_ms: now_ms,
        });
    }
    let reply = self.send(
        t,
        ps,
        Some((stage.clone(), number)),
        REVISE,
        Body::WorkflowObject { run, round, text },
        now_ms,
    )?;
    if let Reply::Failed { reason } = &reply
        && !reply.is_no_answer()
    {
        log::warn!(
            "ticket {} {stage}/{number}: Switchboard refused round {round}: {reason}",
            t.id
        );
        if let Err(e) = std::fs::remove_file(&file) {
            log::warn!("{}: {e}", file.display());
        }
    }
    Ok(())
}

/// The reviewer has nothing further, or the rounds ran out: the
/// finalize decision, or finalized outright when the dial says so.
#[allow(clippy::too_many_arguments)]
fn review_done(
    &mut self,
    t: &mut Ticket,
    ps: &mut ProjectState,
    p: &Pipeline,
    stage: &Stage,
    a: &Attempt,
    view: &wire::RunView,
    now_ms: u64,
) -> Result<()> {
    let subject = stage.subject.clone().unwrap_or_default();
    let how = if view.state == RunState::Converged {
        format!("converged after {} round(s)", view.round)
    } else {
        format!("hit its cap of {} rounds", view.cap)
    };
    if p.dial("finalize") == "auto" {
        self.send(
            t,
            ps,
            Some((a.stage.clone(), a.n)),
            "finalize",
            Body::WorkflowFinalize {
                run: view.id.clone(),
            },
            now_ms,
        )?;
        return Ok(());
    }
    let copy = a
        .artifacts
        .get(&subject)
        .map(|p| p.display().to_string())
        .unwrap_or_default();
    self.ensure_decision(
        t,
        ps,
        Ask {
            stage: &stage.name,
            name: "finalize",
            kind: DecisionKind::Permission,
            question: format!(
                "The review of {subject} {how}. The reviewed copy is {copy}. \
                 Finalize it, or revise with --note?"
            ),
            options: &["finalize", "revise", "park"],
            recommendation: Some("finalize".into()),
            attempt: Some((a.stage.clone(), a.n)),
        },
        now_ms,
    )
}

/// The run, not the ticket, names a plan review's sessions: each is
/// recorded on attempt `idx` once, with the kind its view reports,
/// so a report finds it offline. One ask per session for the
/// ticket's life: a session whose record is gone is recorded with
/// no kind, and one whose ask failed otherwise is asked again.
fn note_run_sessions(
    &mut self,
    t: &mut Ticket,
    idx: usize,
    view: &wire::RunView,
    now_ms: u64,
) -> Result<()> {
    let roles = std::iter::once(("reviewer", view.reviewer.clone()))
        .chain(view.planner.clone().map(|id| ("planner", id)));
    for (role, id) in roles {
        if t.attempts[idx].run_sessions.contains_key(role) {
            continue;
        }
        let agent = match self.session_view(&id)? {
            Ok(session) => {
                note_transcript(t, &id, &session, now_ms);
                kind_word(session.kind).to_owned()
            }
            Err(reason) if reason == NO_SUCH_SESSION => String::new(),
            Err(reason) => {
                log::warn!("session {id}: query failed: {reason}");
                continue;
            }
        };
        t.attempts[idx]
            .run_sessions
            .insert(role.to_owned(), RunSession { session: id, agent });
    }
    Ok(())
}

fn poll_workflow(
    &mut self,
    t: &mut Ticket,
    ps: &mut ProjectState,
    p: &Pipeline,
    stage: &Stage,
    a: &Attempt,
    now_ms: u64,
) -> Result<()> {
    let Some(run) = a.run.clone() else {
        return Ok(());
    };
    let view = match self.ask(Body::Workflow { run: run.clone() })? {
        Reply::Workflow { run } => run,
        Reply::Failed { reason } if reason == NO_SUCH_RUN => {
            return self.fail_attempt(
                t,
                ps,
                &a.stage,
                a.n,
                &format!("review run gone: {reason}"),
                now_ms,
            );
        }
        // The app could not answer (busy, timed out on its own
        // thread): nothing is known about the run, so ask again.
        Reply::Failed { reason } => {
            log::warn!(
                "ticket {} {}/{}: workflow query failed: {reason}; asking again",
                t.id,
                a.stage,
                a.context
            );
            return self.save_ticket(t, now_ms);
        }
        other => bail!("workflow query answered {other:?}"),
    };
    let idx = t
        .attempts
        .iter()
        .position(|x| x.stage == a.stage && x.n == a.n)
        .expect("the attempt exists");
    // The card for the ticket is the planner's while the review runs.
    let face = view
        .planner
        .clone()
        .unwrap_or_else(|| view.reviewer.clone());
    t.attempts[idx].session = Some(face);
    if t.attempts[idx].state == AttemptState::Starting {
        t.attempts[idx].state = AttemptState::Running;
    }
    // The planner clone is made after the start reply, so it joins
    // the process list here, the first time it is seen.
    for id in view.planner.iter().chain(std::iter::once(&view.reviewer)) {
        if !t.processes.contains(id) {
            t.processes.push(id.clone());
        }
    }
    self.note_run_sessions(t, idx, &view, now_ms)?;
    self.save_ticket(t, now_ms)?;
    let subject = stage.subject.clone().unwrap_or_default();
    match view.state {
        RunState::Starting | RunState::AwaitingFeedback | RunState::AwaitingResponse => {
            // Back in a round after converging (the user's own
            // feedback round): the finalize question no longer
            // describes the run, and is asked again when it stops.
            self.withdraw_finalize(t, ps, a, now_ms)
        }
        RunState::Converged | RunState::AtCap => {
            self.review_done(t, ps, p, stage, a, &view, now_ms)
        }
        // The reviewer or planner stopped or exited without its
        // round file: the attempt failed like any agent's, and a
        // rerun starts a fresh review.
        RunState::Paused {
            reason,
            failed: true,
        } => {
            // A `paused` question left from a pause the user
            // continued in the app would send `continue` to a run
            // Dispatch no longer polls; `rerun` replaces it.
            cancel_pending(t, a, "paused");
            self.fail_attempt(t, ps, &a.stage, a.n, &format!("review: {reason}"), now_ms)
        }
        RunState::Paused {
            reason,
            failed: false,
        } => self.ensure_decision(
            t,
            ps,
            Ask {
                stage: &stage.name,
                name: "paused",
                kind: DecisionKind::Permission,
                question: format!("The review of {subject} paused: {reason}. Continue it?"),
                options: &["continue", "park"],
                recommendation: None,
                attempt: Some((a.stage.clone(), a.n)),
            },
            now_ms,
        ),
        RunState::Finalized | RunState::HandedOff => {
            t.attempts[idx].state = AttemptState::Complete;
            t.attempts[idx].ended_ms = Some(now_ms);
            log::info!("ticket {} {}/{} finalized", t.id, a.stage, a.context);
            self.save_ticket(t, now_ms)?;
            for session in [Some(view.reviewer.clone()), view.planner.clone()]
                .into_iter()
                .flatten()

        }
    }
}

impl ServiceRecord {
    /// The ledger intent its launch is sent under.
    #[must_use]
    pub fn intent(&self) -> String {
        format!("service:{}:{}:{}", self.stage, self.lane, self.n)
    }
}

impl Ticket {
    /// The name of the secret artifact at `file`, already canonical,
    /// when it is one of any attempt's: what Dispatch never reads.
    #[must_use]
    pub fn secret_at(&self, file: &Path) -> Option<&str> {
        self.attempts.iter().find_map(|a| {
            a.secret.iter().find_map(|name| {
                let path = a.artifacts.get(name)?;
                let path = path.canonicalize().unwrap_or_else(|_| path.clone());
                (path == file).then_some(name.as_str())
            })
        })
    }

    /// The indexes of the ledger's operations recovery still has to
    /// resolve.
    #[must_use]
    pub fn unsettled(&self) -> Vec<usize> {
        self.unsettled_where(|_| true)
    }

    /// `unsettled`, launches only: what parking and closing wait on,
    /// since a launch still in flight would bring up a session after
    /// they stopped everything.
    #[must_use]
    pub fn unsettled_creations(&self) -> Vec<usize> {
        self.unsettled_where(|o| o.class == "creation")
    }

    fn unsettled_where(&self, keep: impl Fn(&Operation) -> bool) -> Vec<usize> {
        self.ledger
            .iter()
            .enumerate()
            .filter(|(_, o)| keep(o) && o.unresolved())
            .map(|(i, _)| i)
            .collect()
    }

    /// The attempts of stage `stage`, latest numbers last.
    pub fn attempts_of<'a>(&'a self, stage: &'a str) -> impl Iterator<Item = &'a Attempt> + 'a {
        self.attempts.iter().filter(move |a| a.stage == stage)
    }

    /// The most recent completed attempt of any stage that wrote `name`.
    #[must_use]
    pub fn input(&self, name: &str) -> Option<&PathBuf> {
        self.input_with_stage(name).map(|(_, path)| path)
    }

    /// The same, with the stage whose attempt wrote it: a reader is told
    /// whose notes these are when a later stage wrote none.
    #[must_use]
    pub fn input_with_stage(&self, name: &str) -> Option<(&str, &PathBuf)> {
        self.input_where(name, |_| true)
    }

    /// The most recent completed attempt that wrote `name` among those
    /// `keep` accepts, with its stage: a lane's reader keeps only the
    /// attempts it can see.
    #[must_use]
    pub fn input_where(
        &self,
        name: &str,
        keep: impl Fn(&Attempt) -> bool,
    ) -> Option<(&str, &PathBuf)> {
        self.attempts
            .iter()
            .rev()
            .filter(|a| a.state == AttemptState::Complete && !a.forgotten.contains_key(name))
            .filter(|a| keep(a))
            .find_map(|a| a.artifacts.get(name).map(|p| (a.stage.as_str(), p)))
    }

    /// `shown_where` with no filter.
    #[must_use]
    pub fn shown(&self, name: &str) -> Option<(&Attempt, &PathBuf)> {
        self.shown_where(name, |_| true)
    }

    /// `input_where` for a reader who wants the document as it stands: a
    /// workflow attempt still open counts too, since a review edits its
    /// copy in place until `finalize` is answered. Display only; an agent
    /// is handed `input_where`'s complete files.
    #[must_use]
    pub fn shown_where(
        &self,
        name: &str,
        keep: impl Fn(&Attempt) -> bool,
    ) -> Option<(&Attempt, &PathBuf)> {
        self.attempts
            .iter()
            .rev()
            .filter(|a| !a.forgotten.contains_key(name))
            .filter(|a| {
                a.state == AttemptState::Complete
                    || (a.kind == AttemptKind::Workflow && a.is_open())
            })
            .filter(|a| keep(a))
            .find_map(|a| a.artifacts.get(name).map(|p| (a, p)))
    }

    #[must_use]
    pub fn pending_decisions(&self) -> Vec<&Decision> {
        self.decisions.iter().filter(|d| d.pending()).collect()
    }

    /// The pending decisions that wait on the user and count against
    /// the project's limit: while the ticket is closing, only a `stuck`
    /// question, which the close waits on; its other pending decisions
    /// are on their way to cancelled. Every count and every view reads
    /// this, so the rule lives in one place.
    #[must_use]
    pub fn waiting_on_you(&self) -> Vec<&Decision> {
        let closing = matches!(self.state, TicketState::Closing { .. });
        self.pending_decisions()
            .into_iter()
            .filter(|d| !closing || d.name == STUCK)
            .collect()

